class SpiderSpec(object):
    def __init__(self, project, name, spider, items, extractors):
        self.project = project
        self.name = name
        self._spider = spider
        self._items = items
        self._extractors = extractors

    @property
    def spider(self):
        return copy.deepcopy(self._spider)

